import { mkdir, writeFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';

const outputPath = resolve(process.cwd(), 'docs/generated/skopos/api-reference-note.md');
const contents = [
  '# API Reference Note',
  '',
  'Generated by the fixture API reference workflow.',
  '',
  '- workflow: `reference.refresh-api-note`',
  '- purpose: prove required workflow evidence for API changes',
  '',
].join('\n');

await mkdir(dirname(outputPath), { recursive: true });
await writeFile(outputPath, contents, 'utf8');
